      "model": "kimi/k3",
      "tools": {
        "task": false
      },
      "permission": {
        "external_directory": "allow"
      }
    },
    "candidate_d": {
      "description": "Subagent D.",
      "mode": "subagent",
      "model": "kimi/k3",
      "tools": {
        "task": false
      },
      "permission": {
        "external_directory": "allow"
      }
    }
  }
}
